// One direct-hit trigger, four automatic visual stabs, one damage pulse. Snapshot-owned timing.
export function chargeSwordBurst(run, enemy, hit, effective, loadout) {
  const s=run.state, rank=loadout.growthVersion===1 ? loadout.passive?.sj_gate||0 : 0
  if (!rank || !hit.direct || hit.scaled || !(effective>0) || hit.source==='sword_burst') return
  if ((s.swordBurstReadyAt||0)>s.time) return
  s.swordBurstReadyAt=s.time+4
  const id=run._id('burst'),radius=run._passive('sj_gate','radius',loadout)
  const pending={id,targetId:enemy.id,targetRadius:enemy.radius,x:enemy.x,y:enemy.y,radius,
    damage:s.player.attack*run._passive('sj_gate','proc_damage',loadout),
    dueAt:s.time+.42,startedAt:s.time}
  s.swordBursts ||= []
  s.swordBursts.push(pending)
  run._effect('sword_burst_charge',enemy.x,enemy.y,radius,{targetId:enemy.id,burstId:id})
}

export function tickSwordBursts(run) {
  const s=run.state
  if(!s.swordBursts?.length)return
  const ready=s.swordBursts.filter(b=>b.dueAt<=s.time+1e-9)
  s.swordBursts=s.swordBursts.filter(b=>b.dueAt>s.time+1e-9)
  for(const b of ready){
    const targets=run._targets(b,b.radius).sort((a,c)=>
      Number(c.id===b.targetId)-Number(a.id===b.targetId)).slice(0,6)
    const hits=[]
    for(const e of targets){
      const before=e.hp,dx=e.x-b.x,dy=e.y-b.y
      run._damageEnemy({target:e.id,damage:b.damage,direct:false,scaled:false,source:'sword_burst',
        impact:{skill:'sj_gate',dirX:dx||1,dirY:dy,pulseIndex:1,pulseCount:1,castId:b.id}})
      if(e.hp<before)hits.push(e.id)
    }
    run._effect('sword_burst',b.x,b.y,b.radius,{burstId:b.id,targetId:b.targetId,targetRadius:b.targetRadius,targetIds:hits})
  }
}

export function validSwordBursts(s) {
  const finite=x=>Number.isFinite(x)&&x>=0
  if(s.swordBursts!==undefined && (!Array.isArray(s.swordBursts)||s.swordBursts.length>2000||
    !s.swordBursts.every(b=>b&&typeof b.id==='string'&&typeof b.targetId==='string'&&
      [b.x,b.y].every(Number.isFinite)&&[b.radius,b.damage,b.dueAt,b.startedAt].every(finite)&&
      b.radius>0&&b.dueAt>=b.startedAt&&b.dueAt<=b.startedAt+.421)))return false
  return s.swordBurstReadyAt===undefined || finite(s.swordBurstReadyAt)
}
